const pendingTransferIDs = `-- name: PendingTransferIDs :many
SELECT id
FROM payment.transfers
WHERE status = 'PENDING' AND updated_at <= $1 AND id > $2
ORDER BY id
LIMIT $3
`

type PendingTransferIDsParams struct {
	IdleBefore time.Time
	AfterID    uuid.UUID
	Batch      int32
}

// 週期掃描：PENDING、閒置超過門檻的轉帳（job 掉了的保底；每次呼叫都會更新 updated_at，重試中的不會被重複排；ANOMALY 不在內，partial index transfers_pending）。
func (q *Queries) PendingTransferIDs(ctx context.Context, arg PendingTransferIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, pendingTransferIDs, arg.IdleBefore, arg.AfterID, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

